import{_ as p,r as s,o,c as l,e as n,a as c,s as i}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"Partials - October CMS - 4.x","titleTemplate":false,"description":"Reuse chunks of HTML code anywhere in website.","frontmatter":{"subtitle":"Reuse chunks of HTML code anywhere in website."},"headers":[{"level":2,"title":"Rendering Partials","slug":"rendering-partials","link":"#rendering-partials","children":[]},{"level":2,"title":"Passing Variables to Partials","slug":"passing-variables-to-partials","link":"#passing-variables-to-partials","children":[{"level":3,"title":"Variable Scope","slug":"variable-scope","link":"#variable-scope","children":[]},{"level":3,"title":"Parsing Markup as a Variable","slug":"parsing-markup-as-a-variable","link":"#parsing-markup-as-a-variable","children":[]}]},{"level":2,"title":"Props and Attributes","slug":"props-and-attributes","link":"#props-and-attributes","children":[{"level":3,"title":"Declaring Props","slug":"declaring-props","link":"#declaring-props","children":[]},{"level":3,"title":"The Attributes Variable","slug":"the-attributes-variable","link":"#the-attributes-variable","children":[]},{"level":3,"title":"Composable Partials with Props","slug":"composable-partials-with-props","link":"#composable-partials-with-props","children":[]}]},{"level":2,"title":"Dynamic Partials","slug":"dynamic-partials","link":"#dynamic-partials","children":[{"level":3,"title":"Partial Execution Life Cycle","slug":"partial-execution-life-cycle","link":"#partial-execution-life-cycle","children":[]},{"level":3,"title":"Calling AJAX Handlers in Partials","slug":"calling-ajax-handlers-in-partials","link":"#calling-ajax-handlers-in-partials","children":[{"level":4,"title":"See Also","slug":"see-also","link":"#see-also","children":[]}]}]}],"relativePath":"4.x/cms/themes/partials.md","filePath":"4.x/cms/themes/partials.md"}'),u={name:"4.x/cms/themes/partials.md"};function r(g,a,d,k,h,m){const t=s("pre-heading"),e=s("post-heading");return o(),l("div",null,[n(t),a[0]||(a[0]=c("h1",null,"Partials",-1)),n(e),a[1]||(a[1]=i(`<p>Partials are powerful elements that can repeat HTML on different pages or layouts, for example, a page footer used across different <a href="./layouts.html">page layouts</a>. Partials are also a powerful tool for dynamically <a href="./../../ajax/update-partials.html">updating the page content with AJAX</a>.</p><p>Partial templates files reside in the <strong>partials</strong> directory in your theme. Partial files should have the <strong>htm</strong> extension. Next is an example of the simplest possible partial.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>This is a partial<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>A configuration section is optional for partials and can contain the optional <strong>description</strong> parameter that is displayed in the backend user interface. This example shows a partial with a description defined.</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">description</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Demo partial</span>&quot;</span>
</code></pre></div><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>This is a partial<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
</code></pre></div></div><p>The partial configuration section can also contain component definitions. The <a href="./components.html">Components article</a> explains components in more detail.</p><h2 id="rendering-partials"><a href="#rendering-partials" class="header-anchor">#</a> Rendering Partials</h2><div class="custom-block aside"><p>Remember that if you refer a partial from a subdirectory you should specify the subdirectory name.</p></div><p>The <code>{% partial &quot;partial-name&quot; %}</code> Twig tag renders a partial. The tag has a single required parameter - the partial file name without the extension. The <code>{% partial %}</code> tag can be used inside a page, layout or another partial. The following is an example of a page referring to a partial.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>sidebar<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&quot;</span>sidebar-contacts<span class="token punctuation">&quot;</span></span> <span class="token delimiter punctuation">%}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h2 id="passing-variables-to-partials"><a href="#passing-variables-to-partials" class="header-anchor">#</a> Passing Variables to Partials</h2><p>You will find that you often need to pass variables to a partial from the external code. This makes partials even more useful. For example, you can have a partial that renders a list of blog posts. If you can pass the post collection to the partial, the same partial could be used on the blog archive page, on the blog category page and so on. You can pass variables to partials by specifying them after the partial name in the <code>{% partial %}</code> tag.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>sidebar<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&quot;</span>blog-posts<span class="token punctuation">&quot;</span></span> posts<span class="token operator">=</span>posts <span class="token delimiter punctuation">%}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>You can also provide new variables for use in the partial.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>sidebar<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&quot;</span>sidebar-contacts<span class="token punctuation">&quot;</span></span> city<span class="token operator">=</span><span class="token string"><span class="token punctuation">&quot;</span>Vancouver<span class="token punctuation">&quot;</span></span> country<span class="token operator">=</span><span class="token string"><span class="token punctuation">&quot;</span>Canada<span class="token punctuation">&quot;</span></span> <span class="token delimiter punctuation">%}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>Inside the partial, variables can be accessed like any other markup variable.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>Country: <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> country <span class="token delimiter punctuation">}}</span></span>, city: <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> city <span class="token delimiter punctuation">}}</span></span>.<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h3 id="variable-scope"><a href="#variable-scope" class="header-anchor">#</a> Variable Scope</h3><p>The partial contents will have access to the variables from the current context and the additional ones provided.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&quot;</span>mypartial<span class="token punctuation">&quot;</span></span> foo<span class="token operator">=</span><span class="token string"><span class="token punctuation">&quot;</span>bar<span class="token punctuation">&quot;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>In the following example, the <code>foo</code> variable will be available inside the <code>mypartial</code> partial template.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> foo <span class="token operator">=</span> <span class="token string"><span class="token punctuation">&quot;</span>bar<span class="token punctuation">&quot;</span></span> <span class="token delimiter punctuation">%}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&quot;</span>mypartial<span class="token punctuation">&quot;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>You can disable access to the context by appending the <code>only</code> keyword. In this example, only the <code>foo</code> variable will be accessible.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&quot;</span>mypartial<span class="token punctuation">&quot;</span></span> foo<span class="token operator">=</span><span class="token string"><span class="token punctuation">&quot;</span>bar<span class="token punctuation">&quot;</span></span> only <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>In the next example, no variables will be accessible.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&quot;</span>mypartial<span class="token punctuation">&quot;</span></span> only <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h3 id="parsing-markup-as-a-variable"><a href="#parsing-markup-as-a-variable" class="header-anchor">#</a> Parsing Markup as a Variable</h3><p>It is possible to pass markup to a partial by adding the <code>body</code> attribute to the partial tag.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&quot;</span>card<span class="token punctuation">&quot;</span></span> body <span class="token delimiter punctuation">%}</span></span>
    This is the card contents
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endpartial</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>The contents are available inside the partial as the <code>body</code> variable.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> body<span class="token operator">|</span>raw <span class="token delimiter punctuation">}}</span></span>
</code></pre></div><p>Combined with the <a href="./../../markup/tag/placeholder.html">placeholder markup tag</a>, this lets you build composable partials.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&quot;</span>card<span class="token punctuation">&quot;</span></span> image<span class="token operator">=</span><span class="token string"><span class="token punctuation">&quot;</span>img.jpg<span class="token punctuation">&quot;</span></span> body <span class="token delimiter punctuation">%}</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">put</span> header <span class="token delimiter punctuation">%}</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h2</span><span class="token punctuation">&gt;</span></span>This is the card header<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h2</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endput</span> <span class="token delimiter punctuation">%}</span></span>
    This is the card contents
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endpartial</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>The <strong>card</strong> partial is composed of two content areas and an image variable.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>header<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>image<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>img</span> <span class="token attr-name">src</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> image <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">placeholder</span> header <span class="token delimiter punctuation">%}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>body<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> body<span class="token operator">|</span>raw <span class="token delimiter punctuation">}}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h2 id="props-and-attributes"><a href="#props-and-attributes" class="header-anchor">#</a> Props and Attributes</h2><p>Partials can declare which parameters are <strong>props</strong> (template data) and which are <strong>attributes</strong> (HTML pass-through) using the <code>{% props %}</code> tag. This brings a component-style pattern to partials, allowing you to build reusable UI elements with smart class merging and attribute forwarding.</p><h3 id="declaring-props"><a href="#declaring-props" class="header-anchor">#</a> Declaring Props</h3><p>Place the <code>{% props %}</code> tag at the top of a partial <code>.htm</code> file. It uses Twig hash syntax where keys are prop names and values are defaults:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">props</span> <span class="token punctuation">{</span>title<span class="token punctuation">:</span> <span class="token boolean">null</span><span class="token punctuation">,</span> icon<span class="token punctuation">:</span> <span class="token boolean">null</span><span class="token punctuation">,</span> size<span class="token punctuation">:</span> <span class="token string"><span class="token punctuation">&#39;</span>md<span class="token punctuation">&#39;</span></span><span class="token punctuation">}</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><ul><li>Keys listed in <code>{% props %}</code> become Twig variables (props), values are their defaults</li><li>Parameters <strong>not</strong> listed flow into the <code>attributes</code> bag</li><li>An empty <code>{% props {} %}</code> means all parameters go to attributes</li></ul><h3 id="the-attributes-variable"><a href="#the-attributes-variable" class="header-anchor">#</a> The Attributes Variable</h3><p>When <code>{% props %}</code> is present, the template receives an <code>attributes</code> variable — an instance of Laravel&#39;s <code>ComponentAttributeBag</code>. It supports smart class merging where the caller&#39;s classes are appended to the partial&#39;s defaults.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token comment">{# partials/ui/card.htm #}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">props</span> <span class="token punctuation">{</span>title<span class="token punctuation">:</span> <span class="token boolean">null</span><span class="token punctuation">}</span> <span class="token delimiter punctuation">%}</span></span>

<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name"><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> attributes<span class="token punctuation">.</span>merge<span class="token punctuation">(</span><span class="token punctuation">{</span>class<span class="token punctuation">:</span> <span class="token string"><span class="token punctuation">&#39;</span>card<span class="token punctuation">&#39;</span></span><span class="token punctuation">}</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span></span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h2</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> title <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h2</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> body <span class="token delimiter punctuation">}}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&quot;</span>ui/card<span class="token punctuation">&quot;</span></span> title<span class="token operator">=</span><span class="token string"><span class="token punctuation">&quot;</span>Hello<span class="token punctuation">&quot;</span></span> class<span class="token operator">=</span><span class="token string"><span class="token punctuation">&quot;</span>mt-4 shadow<span class="token punctuation">&quot;</span></span> id<span class="token operator">=</span><span class="token string"><span class="token punctuation">&quot;</span>featured<span class="token punctuation">&quot;</span></span> body <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>Card content goes here<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endpartial</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>The <code>title</code> parameter is a prop and becomes a template variable. The <code>class</code> and <code>id</code> parameters are not listed in props, so they flow into the attribute bag. The <code>merge</code> method appends the caller&#39;s <code>class</code> to the default, producing <code>class=&quot;card mt-4 shadow&quot;</code>.</p><div class="custom-block tip"><p>See the <a href="./../../markup/tag/props.html">Props Twig Tag</a> for the full attribute bag API including <code>only()</code>, <code>except()</code>, <code>has()</code>, and <code>get()</code> methods.</p></div><h3 id="composable-partials-with-props"><a href="#composable-partials-with-props" class="header-anchor">#</a> Composable Partials with Props</h3><p>The existing <code>{% put %}</code> / <code>{% placeholder %}</code> system works alongside <code>{% props %}</code> for partials that need multiple content sections:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token comment">{# Caller #}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&quot;</span>card<span class="token punctuation">&quot;</span></span> class<span class="token operator">=</span><span class="token string"><span class="token punctuation">&quot;</span>shadow<span class="token punctuation">&quot;</span></span> body <span class="token delimiter punctuation">%}</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">put</span> header <span class="token delimiter punctuation">%}</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h2</span><span class="token punctuation">&gt;</span></span>Card Title<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h2</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endput</span> <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>Body content<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endpartial</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token comment">{# card.htm #}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">props</span> <span class="token punctuation">{</span><span class="token punctuation">}</span> <span class="token delimiter punctuation">%}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name"><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> attributes<span class="token punctuation">.</span>merge<span class="token punctuation">(</span><span class="token punctuation">{</span>class<span class="token punctuation">:</span> <span class="token string"><span class="token punctuation">&#39;</span>card<span class="token punctuation">&#39;</span></span><span class="token punctuation">}</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span></span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>card-header<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
        <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">placeholder</span> header <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>card-body<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> body <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h2 id="dynamic-partials"><a href="#dynamic-partials" class="header-anchor">#</a> Dynamic Partials</h2><p>Partials, like pages, can use any Twig features. Please refer to the <a href="./pages.html">Dynamic Pages section</a> of the documentation for details.</p><h3 id="partial-execution-life-cycle"><a href="#partial-execution-life-cycle" class="header-anchor">#</a> Partial Execution Life Cycle</h3><p>There are special functions that can be defined in the PHP section of partials: <code>onStart</code> and <code>onEnd</code>. The <code>onStart</code> function is executed before the partial is rendered and before the <a href="./components.html">partial components</a> are executed. The <code>onEnd</code> function is executed before the partial is rendered and after the partial components are executed. In the <code>onStart</code> and <code>onEnd</code> functions you can inject variables to the Twig environment. Use the <code>$this</code> with array notation to pass variables to the page.</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code></code></pre></div><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?</span>
<span class="token keyword">function</span> <span class="token function-definition function">onStart</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;hello&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token string double-quoted-string">&quot;Hello world!&quot;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
<span class="token delimiter important">?&gt;</span></span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h3</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> hello <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h3</span><span class="token punctuation">&gt;</span></span>
</code></pre></div></div><p>Externally assigned variables to the partial can be accessed in PHP using the <code>$this</code> object.</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code></code></pre></div><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?</span>
<span class="token keyword">function</span> <span class="token function-definition function">onStart</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;location&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">city</span> <span class="token operator">.</span> <span class="token string single-quoted-string">&#39;, &#39;</span> <span class="token operator">.</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">country</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
<span class="token delimiter important">?&gt;</span></span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> location <span class="token delimiter punctuation">}}</span></span> is the same as <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> city <span class="token delimiter punctuation">}}</span></span>, <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> country <span class="token delimiter punctuation">}}</span></span>.<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
</code></pre></div></div><p>The templating language provided by October CMS is described in the <a href="./../../markup/templating.html">Markup Guide</a>. The overall sequence the handlers are executed is described in the <a href="./layouts.html">Dynamic Layouts section</a> of the documentation.</p><h3 id="calling-ajax-handlers-in-partials"><a href="#calling-ajax-handlers-in-partials" class="header-anchor">#</a> Calling AJAX Handlers in Partials</h3><p>Since they are instantiated late, during the time the page is rendered, some limitations apply to the life cycle of regular partials. To overcome this, you may use the <code>{% ajaxPartial %}</code> to allow AJAX handlers to be called inside your partial.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">ajaxPartial</span> <span class="token string"><span class="token punctuation">&quot;</span>contact-form<span class="token punctuation">&quot;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><div class="custom-block tip"><p>See the <a href="./../../markup/tag/ajax-partial.html">AJAX Partial Twig Tag article</a> to learn more about the <code>{% ajaxPartial %}</code> tag.</p></div><p>When calling a handler from within an AJAX partial, the life cycle operates differently compared to a regular AJAX handler.</p><ol><li>The handler runs after the partial&#39;s <code>onEnd</code> function.</li><li>The complete page life cycle runs, including logic in the layout, page and parent partials.</li><li>All variables are available during the request, including variables set using Twig.</li><li>The partial life cycle functions do not support returning any values.</li></ol><h4 id="see-also"><a href="#see-also" class="header-anchor">#</a> See Also</h4><div class="custom-block also"><ul><li><a href="./../../markup/tag/partial.html">Partial Twig Tag</a></li><li><a href="./../../markup/tag/props.html">Props Twig Tag</a></li><li><a href="./../../markup/tag/ajax-partial.html">AJAX Partial Twig Tag</a></li></ul></div>`,67))])}const b=p(u,[["render",r]]);export{v as __pageData,b as default};
